const item = $input.first();
const jobTitle = item.json.body?.job_title || '';
const jobDescription = item.json.body?.job_description || '';

const binaryKey = Object.keys(item.binary || {})[0];
if (!binaryKey) throw new Error('Nenhum PDF enviado');

const pdfBuffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const pdfName = item.binary[binaryKey].fileName || 'curriculo.pdf';

const boundary = '----FormBoundary7MA4YWxkTrZu0gW';
const parts = [];

parts.push(`--${boundary}\r\nContent-Disposition: form-data; name="curriculum"; filename="${pdfName}"\r\nContent-Type: application/pdf\r\n\r\n`);
parts.push(pdfBuffer);
parts.push(`\r\n--${boundary}\r\nContent-Disposition: form-data; name="job_title"\r\n\r\n${jobTitle}`);
parts.push(`\r\n--${boundary}\r\nContent-Disposition: form-data; name="job_description"\r\n\r\n${jobDescription}`);
parts.push(`\r\n--${boundary}--\r\n`);

const bodyParts = [];
for (const part of parts) {
  if (typeof part === 'string') {
    bodyParts.push(Buffer.from(part, 'utf-8'));
  } else {
    bodyParts.push(part);
  }
}
const body = Buffer.concat(bodyParts);

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://host.docker.internal:8001/analyze',
  headers: {
    'Content-Type': `multipart/form-data; boundary=${boundary}`,
  },
  body: body,
  json: false,
  returnFullResponse: false,
  timeout: 120000,
});

return [{ json: typeof response === 'string' ? JSON.parse(response) : response }];

